<?php
use Illuminate\Contracts\Http\Kernel; use Illuminate\Http\Request;
putenv('SESSION_DRIVER=array'); putenv('CACHE_STORE=array'); putenv('QUEUE_CONNECTION=sync');
require __DIR__.'/../vendor/autoload.php'; $app=require __DIR__.'/../bootstrap/app.php'; $request=Request::create('/', 'GET'); $response=$app->make(Kernel::class)->handle($request);
if($response->getStatusCode()!==200) throw new RuntimeException('Homepage did not return HTTP 200.'); $dist=__DIR__.'/../dist'; if(!is_dir($dist)) mkdir($dist,0777,true); $html=preg_replace('#https?://[^/]+/build/#','/tresomnium/build/',$response->getContent()); $html=preg_replace('#<script[^>]*>.*?localhost/_boost/browser-logs.*?</script>#s','',$html); file_put_contents($dist.'/index.html',$html);
$source=__DIR__.'/../public/build'; if(!is_dir($source)) throw new RuntimeException('Vite output not found.'); $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($source,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST); foreach($it as $file){$to=$dist.'/build/'.$it->getSubPathName(); if($file->isDir()){if(!is_dir($to))mkdir($to,0777,true);}else{if(!is_dir(dirname($to)))mkdir(dirname($to),0777,true);copy($file->getPathname(),$to);}} $fonts=__DIR__.'/../resources/fonts'; if(is_dir($fonts)){if(!is_dir($dist.'/fonts'))mkdir($dist.'/fonts',0777,true);foreach(glob($fonts.'/*') as $font)copy($font,$dist.'/fonts/'.basename($font));} file_put_contents($dist.'/.nojekyll',''); $app->make(Kernel::class)->terminate($request,$response);
